********************************************************************************** Various assembly-language routines for Teach** Copyright 1989-1993 Apple Computer, Inc.* All Rights Reserved*********************************************************************************	include 'All.Macros'********************************************************************************** InstallMyRequestProc** Install the request procedure that will respond to srqQuit, srqOpenOrPrint,* and any other request we feel like watching for.*********************************************************************************InstallMyRequestProc proc export	pushlong #reqProcName	pha	_MMStartUp	pushlong #teachReqProc	_AcceptRequests	rtlreqProcName	str 'Apple~Teach~'********************************************************************************* teachReqProc** This is Teach's request procedure.********************************************************************************teachReqProcoldDPage	equ 1RTL1	equ oldDPage+2DataOut	equ RTL1+3DataIn	equ DataOut+4Request	equ DataIn+4Result	equ Request+2		phd	tsc	tcd		phb	phk	plb	lda requestTable	pha	lda <Request	sta requestTable	ldx #requestTableEnd-requestTable@search	dex	dex	dex	dex	cmp requestTable,x	bne @search	jsr (requestTable+2,x)	;return SEC = handled	ror <Result	pla	sta requestTable	plb	pld	lda 2,s	sta 12,s	lda 1,s	sta 11,s	ply	ply	ply	ply	ply	rtlrequestTable	dc.w $7777,ignoreRequest	dc.w $0010,handleOpenOrPrint	;srqOpenOrPrint	dc.w $0011,handleQuit	;srqQuitrequestTableEndignoreRequest	clc	rts********************************************************************************* handleQuit** Respond to a srqQuit request.** dataIn = dataOut = reserved** Return with SEC if we handled the request.********************************************************************************	import srqQuitFlaghandleQuit	lda #1	sta >srqQuitFlag	sec	rts********************************************************************************* handleOpenOrPrint** Respond to a srqOpenOrPrint request (re-check message $0011).** dataIn = dataOut = reserved** Return with SEC if we handled the request.********************************************************************************	import LaunchDochandleOpenOrPrint	pha	jsl LaunchDoc	pla	cmp #1	;SEC on nonzero result	rts	EndP********************************************************************************** ComplainAboutSysVersion (30-Sep-91 DAL)** On the stack:*    4-5:  error code*    1-3:  RTL*********************************************************************************ComplainAboutSysVersion proc exporterrorCode	equ 4	lda errorCode,s	pha	pha	;space for HexIt	pha	;error code	_HexIt	pla	sta >theErrorCode	pla	sta >theErrorCode+2	pha	;space for result	pea Line1>>16	pea Line1	pea Line2>>16	pea Line2	pea Button1>>16	pea Button1	pea OKStrText>>16	pea OKStrText	_TLTextMountVolume	pla	;discard result*** strip input parameter (word) from stack	lda 2,s	sta 2+2,s	lda 1,s	sta 1+2,s	pla	rtlLine1	dc.b EndLine1-*-1,'You must start up from System 6.0.1'EndLine1Line2	dc.b EndLine2-*-1,'or later to run Teach.  ($'theErrorCode	dc.b 'xxxx)'EndLine2;; text OK button string for TLTextMountVolume; spaces push Button2 (left button) to the right (to right-justify it);   (can’t be Button1 because escape chars are counted in Button1’s right justification!); $1B: ESC to enable mousetext in the firmware; $0F: turns on Inverse; ‘M’ is mousetext for return char; $0E: turns off inverse; $18: Ctrl-X to disable mousetext in the firmware;OKStrText	dc.b EndOKStrText-*-1,'                           Quit '	dc.b $0f,$1b,'M',$0E,$18EndOKStrTextButton1	dc.b 0	EndP********************************************************************************TestChangeFlag	Proc Export;; Function TestChangeFlag(theWindow:GrafPortPtr):Boolean;;fRecordDirty	equ  $0040; This function will test the fRecordDirty field in the control record to see if; it is set, and then it will return true or false depending on the flag state.;OldDPage	equ 1RTL1	equ OldDPage+2WindPtr	equ RTL1+3Result	equ WindPtr+4	phd	tsc	tcd	; set up a stack frame...		stz <Result;; Now get the control handle...	pha	pha	PushLong <WindPtr	pea 0	; high word of ID=0	pea $1000	; main window ID	_GetCtlHandleFromID	; get the control handle	pla	sta <WindPtr	pla	sta <WindPtr+2	ldy #2	; now dereference the control	lda [WindPtr],y	tax	lda [WindPtr]	sta WindPtr	stx WindPtr+2	; and now wind pointer points at the control;; Now that we have a pointer to the control, lets look at the flag field	ldy #$10	; offset to flag field	lda [WindPtr],y	; get the value	and #fRecordDirty	; test the dirty bit..	beq @Done	lda #$FFFF	sta <Result@Done; Now unlink the stack and end...	pld	; recover the saved direct page	longa off	; save the return address for a second	sep #$20	pla	ply		plx	; yank parms	plx			phy	pha	longa On	; restore return address	rep #$20		RTL	; and exit.	EndP	ResetChangeFlag	Proc Export; procedure ResetChangeFlag(theWindow:GrafPortPtr);;ResetfRecordDirty	equ  $FFBF	; NOT($0040); This function will reset the fRecordDirty field in the control record.;OldDPage	equ 1RTL1	equ OldDPage+2WindPtr	equ RTL1+3	phd	tsc	tcd	; set up a stack frame...;; Now get the control handle...	pha	pha	PushLong <WindPtr	pea 0	; high word of ID=0	pea $1000	; main window ID	_GetCtlHandleFromID	; get the control handle	pla	sta <WindPtr	pla	sta <WindPtr+2	ldy #2	; now dereference the control	lda [WindPtr],y	tax	lda [WindPtr]	sta WindPtr	stx WindPtr+2	; and now wind pointer points at the control;; Now that we have a pointer to the control, lets look at the flag field	ldy #$10	; offset to flag field	lda [WindPtr],y	; get the value	and #ResetfRecordDirty	; reset the dirty bit..	sta [WindPtr],y@Done; Now unlink the stack and end...	pld	; recover the saved direct page	longa off	; save the return address for a second	sep #$20	pla	ply		plx	; yank parms	plx			phy	pha	longa On	; restore return address	rep #$20		RTL	; and exit.	EndP	********************************************************************************;; Assebly code for the pascal function:; Function CompareC1In(str1,str2:ptr);Boolean;;; This function will compare 2 c1Input strings and see if they are the same; It will disregard case in the compare however..;********************************************************************************CompareC1In	Proc Export;; Stack frame to look like this..oldDPage	equ 1RTL	equ oldDPage+2ptr1	equ RTL+3ptr2	equ ptr1+4result	equ ptr2+4	phd	; set up our stack frame	tsc	tcd		stz <Result	; set result to be false...;; First compare string lengths...	lda [ptr1]	cmp [ptr2]	beq @BufLenOK	brl Done;@BufLenOK;; Now we strart from the back of the string and work forwards; and test each byte of the string...	tay	; length already in <A>	iny	; bump it one for good measure...;; This loop tests the next character to see if its proper..@Loop	lda [ptr1],y	and #$00FF	; strip it..	cmp #'A'	blt @got1	cmp #$005B	bge @Got1	ora #$0020@Got1	pha	lda [ptr2],y	and #$00FF	cmp #'A'	blt @Got2	cmp #$005B	bge @Got2	ora #$0020@Got2	cmp 1,s	bne @Fail	pla	dey	bne @Loop	lda #$FFFF	sta <Result	bra Done@Fail	plaDone	pld	; unlink the stack frame and finish..		longa off	sep #$20	pla	ply		plx	plx	plx	plx		phy	pha		rep #$20	longa On	RTL********************************************************************************;; Assembly language	code for the pascal	function:; Function FindNext(theText:ptr; FindWhat:str255; ;	Case:Boolean; length:Longint;;	var CurrentOffset:Longint):Boolean;;; This function will scan a string in search of the passed substring. The search will; be case sensative	if the proper flag is set.; It will update CurrentOffset to the location of the FindWhat string in the; text buffer and return true if the substring was found.;********************************************************************************FindNext	proc Export;; The stack frame will look like this:FindTemp	equ 1FindChar	equ FindTemp+4oldDPage	equ FindChar+2RTL	equ oldDPage+2CurrentOffset	equ RTL+3Length	equ CurrentOffset+4Case	equ Length+4FindWhat	equ Case+2theText	equ FindWhat+4theResult	equ theText+4;; First set up our stack frame...	phd	; and the direct page	pha	pha	pha	tsc	tcd;	;; Start by creating the pointers that I need...	ldy #2	lda [CurrentOffset]	clc	adc <theText	sta <theText	lda [CurrentOffset],y	adc <theText+2	sta <theText+2	lda FindWhat	; get the pointer to the string to find...	inc a	; add 1 to rid ourselves of the length byte	sta <FindTemp	lda FindWhat+2	; its gotta be in the same bank...	sta <FindTemp+2	lda Case	; and adjust the flag..	beq @cont	lda #1	; make it non-negative...	sta Case;; Now since we know that case sensative is yes, lower case the entire input string...	lda [FindWhat]	; get the length of the find string	and #$00FF	tay	; and use it as an index..	bne @Loop00	brl Done	; if the length is zero then ooooops..	@Loop00	lda [FindWhat],y	; get next char...	tax	; save this value in X for a second..	and #$00FF	; strip off the high byte	cmp #$0041	; is it an 'A'	blt @Next00	; if less than A do the next char..	cmp #$005B	bge @Next00	; if greater than Z do next char...	txa	; get the original word back...	ora #$0020	; lower case the sucker..	sta [FindWhat],y	; and save it back..@Next00	dey	; lower the counter by 1	bne @Loop00	; if not zero keep going..	@Cont; Now, start the main loopWhile	ldy #2	lda [CurrentOffset],y ; test the position against the max length...	cmp Length+2	blt @doBegin01	bge @testLow	brl NotFound	; if the high word is bigger its not found..@testLow	lda [CurrentOffset]	; now test the current offset...	cmp Length	blt @DoBegin01	beq @DoBegin01	brl NotFound;; We can look at the next character right now...@DoBegin01	lda case	; case sensative test?	bne @CaseSensative; the following compares the next chars on a non-case basis...		lda [theText]	and #$00FF@NonCaseComp	sta FindChar	lda [FindTemp]	and #$00FF	cmp FindChar	beq @MatchFirst	; The first character matches...	brl @DoNext01@CaseSensative	lda [theText]	and #$00FF	cmp #$0041	; is it an 'A'	blt @NonCaseComp	; if less than A do the next char..	cmp #$005B	bge @NonCaseComp	; if greater than Z do next char...	ora #$0020	; else lower case the sucker	bra @NonCaseComp	; and test it..;; Do next01 increments the pointers counters and then goes back to square 1@DoNext01	lda [CurrentOffset]	inc a	sta [CurrentOffset]	bne @DN010010	ldy #2	lda [CurrentOffset],y	inc a	sta [CurrentOffset],y@DN010010	inc theText	bne WHILE	inc theText+2	brl While;; MatchFirst will be called when the first characters of the strings match...@MatchFirst	lda [FindWhat]	; get the length of the string to match	and #$00FF	; strip the high byte	tay	; transfer this into our pointer...@MFLoop	dey	; decrement our counter...	bne @MFL0010	brl FOUND	; if this gets to zero we found it bunky..;; Now we compare the next char...@MFL0010	lda case	; case sensative test?	bne @MFLCS; the following compares the next chars on a non-case basis...		lda [theText],y	and #$00FF@MFLNCC	sta FindChar	lda [FindTemp],y	and #$00FF	cmp FindChar	beq @MFLoop	; The next character matches...	brl @MFLDone	; else its not found dude..@MFLCS	lda [theText],y	and #$00FF	cmp #$0041	; is it an 'A'	blt @MFLNCC	; if less than A do the next char..	cmp #$005B	bge @MFLNCC	; if greater than Z do next char...	ora #$0020	; else lower case the sucker	bra @MFLNCC	; and test it..@MFLDone	brl @DoNext01	; if no more matches then test the next char...FOUND	lda #$0001	; put true into the result	sta theResult	brl DoneNOTFOUND	lda #$0000	sta theResultDONE; adjust the stack...	longa off	sep #$20	plx	; discard local data...	plx	plx		pld	; recover the old dpage register		pla	ply	; get the return address		plx	; now pull off passed parms...	plx	plx	plx	plx	plx	plx	plx	plx		phy	; restore the return address	pha	longa on		rep #$20	RTL	; and return	EndP	End